def compute(vars):
    change = vars["v2"] - vars["v1"]
    return {
        "value": change,
        "trace": {
            "total_2018": vars["v2"],
            "total_2017": vars["v1"],
            "change": change,
            "output_meta": {
                "currency": "$",
                "scale": "million",
                "unit": "currency"
            }
        }
    }
